namespace companion {namespace {
void need(bool b,const char* s){if(!b)throw std::runtime_error(s);}
bool uuid(const QString& s){return s!="00000000-0000-0000-0000-000000000000"&&QRegularExpression("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\z").match(s).hasMatch();}
bool localId(const QString& s){return uuid(s)||QRegularExpression("^[0-9a-f]{64}\\z").match(s).hasMatch();}
QString newId(){return QUuid::createUuid().toString(QUuid::WithoutBraces);}QByteArray json(const QJsonObject& o){return QJsonDocument(o).toJson(QJsonDocument::Compact);}QString digest(const QByteArray& b){return QString::fromLatin1(underlay::digest(b).toHex());}
void text(const QString& s,int cap,bool empty=true){need((empty||!s.trimmed().isEmpty())&&s.size()<=cap&&!s.contains(QChar(0)),"Tom text bound");}
QByteArray envelope(const QJsonObject& o){return json({{"payload",o},{"sha256",digest(json(o))}});}
void directory(const std::filesystem::path& p){need(p.is_absolute(),"Tom absolute root required");int fd=open("/",O_RDONLY|O_DIRECTORY|O_CLOEXEC);need(fd>=0,"Tom root open");for(auto& component:p.relative_path()){auto name=component.string();if(name.empty()||name=="."||name==".."){close(fd);throw std::runtime_error("Tom path component");}int next=openat(fd,name.c_str(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);close(fd);need(next>=0,"Tom directory unsafe");fd=next;}struct stat st{};int rc=fstat(fd,&st);close(fd);need(!rc&&st.st_uid==getuid()&&!(st.st_mode&0077),"Tom directory ownership");}
QJsonObject read(const std::filesystem::path& p,const char* kind,qint64 cap){directory(p.parent_path());int fd=open(p.c_str(),O_RDONLY|O_NOFOLLOW|O_CLOEXEC);need(fd>=0,"Tom record missing");struct stat st{};if(fstat(fd,&st)||!S_ISREG(st.st_mode)||st.st_uid!=getuid()||st.st_nlink!=1||(st.st_mode&0777)!=0600||st.st_size<=0||st.st_size>cap){close(fd);throw std::runtime_error("Tom record owner mode size");}QByteArray b(st.st_size,Qt::Uninitialized);qsizetype at=0;while(at<b.size()){auto n=::read(fd,b.data()+at,b.size()-at);if(n<0&&errno==EINTR)continue;if(n<=0){close(fd);throw std::runtime_error("Tom record short read");}at+=n;}close(fd);QJsonParseError error;auto doc=QJsonDocument::fromJson(b,&error);need(error.error==QJsonParseError::NoError&&doc.isObject(),"Tom record JSON");auto outer=doc.object();need(outer["payload"].isObject(),"Tom record envelope");auto o=outer["payload"].toObject();need(outer["sha256"].toString()==digest(json(o)),"Tom record checksum");need(o["version"].toInt()==1&&o["record"]==kind,"Tom record schema");return o;}
std::filesystem::path conversationPath(const std::filesystem::path& root,const QString& id){need(uuid(id),"Tom conversation id");return root/"conversations"/id.toStdString();}
std::filesystem::path turnPath(const std::filesystem::path& root,const QString& conversation,const QString& turn){need(uuid(turn),"Tom turn id");return conversationPath(root,conversation)/"turns"/turn.toStdString();}
QJsonObject indexAt(const std::filesystem::path& root){auto o=read(root/"index.json","index",512*1024);need(o["conversations"].isArray()&&o["conversations"].toArray().size()<=128&&o["deleted"].isArray()&&o["deleted"].toArray().size()<=4096,"Tom index capacity");return o;}
bool visible(const QJsonObject& index,const QString& id){if(index.value("deleting")==id||index["deleted"].toArray().contains(id))return false;for(auto v:index["conversations"].toArray())if(v.toObject()["id"]==id)return true;return false;}
QJsonObject manifestAt(const std::filesystem::path& root,const QString& id){auto o=read(conversationPath(root,id)/"manifest.json","conversation",65536);need(o["id"]==id&&o["turns"].isArray()&&o["turns"].toArray().size()<=256,"Tom conversation schema");text(o["title"].toString(),180,false);return o;}
QJsonObject stateAt(const std::filesystem::path& root,const QString& conversation,const QString& turn){auto o=read(turnPath(root,conversation,turn)/"state.json","turn",16*1024*1024);need(o["conversation"]==conversation&&o["turn"]==turn&&o["status"].isString()&&QStringList{"draft","frozen","create-uncertain","receiving","cancel-uncertain","reconciling","completed","canceled","interrupted"}.contains(o["status"].toString())&&o["create_attempted"].isBool()&&o["answer"].isString()&&o["answer"].toString().size()<=262144&&o["cursor"].isDouble()&&o["cursor"].toDouble()>=0&&o["cursor"].toDouble()<=4096&&o["cursor"].toDouble()==o["cursor"].toInt()&&o["events"].isObject()&&o["events"].toObject().size()==o["cursor"].toInt(),"Tom turn schema");return o;}
QJsonObject draftObject(const TomDraft& d){need(QStringList{"general","word","sentences","paragraphs","page"}.contains(d.scope),"Tom draft scope");text(d.question,8000);text(d.correctedText,8000);text(d.interpretation,8000);need(d.interpretationTurn.isEmpty()||uuid(d.interpretationTurn),"Tom interpretation identity");need(d.originalHandwriting.size()<=1024&&QJsonDocument(d.originalHandwriting).toJson(QJsonDocument::Compact).size()<=8*1024*1024,"Tom original handwriting capacity");for(auto image:{d.handwritingImage,d.pageImage})need(image.isEmpty()||(image.size()<=2800000&&(image.startsWith("data:image/png;base64,")||image.startsWith("data:image/jpeg;base64,"))),"Tom draft image bound");if(d.scope=="general")need(d.context.isEmpty()&&d.localDocumentId.isEmpty()&&d.wireAlias.isEmpty()&&d.pageImage.isEmpty(),"Tom general draft source forbidden");else{need(localId(d.localDocumentId)&&uuid(d.wireAlias.isEmpty()?d.localDocumentId:d.wireAlias)&&d.context["document_id"]==(d.wireAlias.isEmpty()?d.localDocumentId:d.wireAlias)&&!d.context["revision"].isNull()&&!d.context["revision"].isUndefined()&&!d.context["anchor"].isNull()&&!d.context["anchor"].isUndefined()&&d.context["text"].isString(),"Tom selected draft binding");text(d.context["text"].toString(),16000);}
 return {{"question",d.question},{"corrected_text",d.correctedText},{"original_handwriting",d.originalHandwriting},{"scope",d.scope},{"context",d.scope=="general"?QJsonValue(QJsonValue::Null):QJsonValue(d.context)},{"local_document_id",d.localDocumentId},{"wire_alias",d.wireAlias},{"handwriting_image",d.handwritingImage},{"page_image",d.pageImage},{"interpretation",d.interpretation},{"interpretation_turn",d.interpretationTurn}};}
TomDraft decodeDraft(const QJsonObject& o){TomDraft d{o["question"].toString(),o["corrected_text"].toString(),o["original_handwriting"].toArray(),o["scope"].toString(),o["context"].toObject(),o["local_document_id"].toString(),o["wire_alias"].toString(),o["handwriting_image"].toString(),o["page_image"].toString(),o["interpretation"].toString(),o["interpretation_turn"].toString()};auto normalized=o;if(!normalized.contains("interpretation"))normalized["interpretation"]="";if(!normalized.contains("interpretation_turn"))normalized["interpretation_turn"]="";need(draftObject(d)==normalized,"Tom draft schema");return d;}
QJsonObject uiContext(const TomDraft& d){if(d.scope=="general")return {{"scope","general"}};auto anchor=d.context["anchor"].toObject();anchor["scope"]=d.scope;anchor["document"]=d.localDocumentId;anchor["revision"]=d.context["revision"];if(!anchor.contains("excerpt"))anchor["excerpt"]=d.context["text"];return anchor;}
QJsonObject provenance(const TomDraft& d){draftObject(d);bool safe=d.scope=="general"&&d.context.isEmpty()&&d.handwritingImage.isEmpty()&&d.pageImage.isEmpty();return {{"scope",d.scope},{"local_document_id",d.localDocumentId},{"wire_alias",d.wireAlias},{"context",d.scope=="general"?QJsonValue(QJsonValue::Null):QJsonValue(d.context)},{"general_history_safe",safe}};}
// What a frozen request is bound to. A read-and-answer request's handwriting image is its question (later history
// carries only what was read and the answer), so it is bound as the same draft without the image. Every other purpose
// is bound exactly as before: records written by earlier builds must keep matching, or opening the store fails.
QJsonObject boundProvenance(TomDraft d,const QString& purpose){if(purpose=="read-answer")d.handwritingImage.clear();return provenance(d);}
QJsonObject historyProvenance(TomDraft d,const QString& purpose){if(purpose=="read-auto-answer"||purpose=="read-auto-scene-answer")d.handwritingImage.clear();return boundProvenance(d,purpose);}
QJsonObject configObject(const TomConfig& c){QJsonArray models;for(auto m:c.models)models.append(m);return {{"configured",c.configured},{"provider",QJsonObject{{"id",c.provider},{"label",c.label}}},{"models",models},{"max_output_tokens",c.maxOutputTokens},{"daily_limit",c.dailyLimit}};}
QJsonObject frozenAt(const std::filesystem::path& root,const QString& conversation,const QString& turn){auto o=read(turnPath(root,conversation,turn)/"frozen.json","frozen",12*1024*1024);need(o["conversation"]==conversation&&o["turn"]==turn&&uuid(o["request_id"].toString())&&uuid(o["device_id"].toString())&&o["wire_body"].isString()&&digest(o["wire_body"].toString().toUtf8())==o["wire_fingerprint"].toString()&&digest(json(o["provenance"].toObject()))==o["context_fingerprint"].toString(),"Tom frozen binding");auto c=parseTomConfig(json(o["config"].toObject()));need(c.fingerprint==o["config_fingerprint"].toString().toLatin1(),"Tom frozen configuration");QJsonParseError error;auto body=QJsonDocument::fromJson(o["wire_body"].toString().toUtf8(),&error);need(error.error==QJsonParseError::NoError&&body.isObject()&&body.object()["request_id"]==o["request_id"]&&body.object()["conversation_id"]==conversation,"Tom frozen request identity");return o;}
bool terminal(const QString& s){return s=="completed"||s=="canceled"||s=="interrupted";}
void purge(int fd,unsigned& count){DIR* dir=fdopendir(dup(fd));need(dir,"Tom delete directory");try{while(auto* entry=readdir(dir)){std::string name=entry->d_name;if(name=="."||name=="..")continue;need(++count<=4096,"Tom delete capacity");struct stat st{};need(!fstatat(fd,name.c_str(),&st,AT_SYMLINK_NOFOLLOW)&&st.st_uid==getuid(),"Tom delete ownership");if(S_ISDIR(st.st_mode)){int child=openat(fd,name.c_str(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);need(child>=0,"Tom delete child");try{purge(child,count);}catch(...){close(child);throw;}close(child);need(!unlinkat(fd,name.c_str(),AT_REMOVEDIR),"Tom delete directory unlink");}else{need(S_ISREG(st.st_mode)&&st.st_nlink==1&&(st.st_mode&0777)==0600,"Tom delete file type");need(!unlinkat(fd,name.c_str(),0),"Tom delete file unlink");}}closedir(dir);dir=nullptr;need(!fsync(fd),"Tom delete directory sync");}catch(...){if(dir)closedir(dir);throw;}}
}
namespace {
// Opening the store re-checks every turn (state, draft with its handwriting image, frozen request and their digests).
// A turn that is no longer a draft is only validated, never repaired, so once this process has validated it and its
// files are byte-for-byte the same files (inode, size, nanosecond mtime of state/draft/frozen), checking it again
// cannot change the outcome. The runtime opens the store several times per send and the helper once per streamed
// event; without this every open cost time proportional to the whole Tom history.
std::string turnStamp(const std::filesystem::path& turn){
 std::string key=turn.string();for(const char* name:{"state.json","draft.json","frozen.json"}){struct stat st{};const auto f=turn/name;
  if(lstat(f.c_str(),&st)==0)key+="|"+std::to_string(st.st_ino)+":"+std::to_string(st.st_size)+":"+std::to_string(st.st_mtim.tv_sec)+"."+std::to_string(st.st_mtim.tv_nsec);else key+="|-";}
 return key;}
std::mutex& validatedMutex(){static std::mutex m;return m;}
std::unordered_set<std::string>& validatedTurns(){static std::unordered_set<std::string> s;return s;}
bool validatedTurn(const std::string& stamp){std::lock_guard lock(validatedMutex());return validatedTurns().contains(stamp);}
void rememberTurn(const std::string& stamp){std::lock_guard lock(validatedMutex());if(validatedTurns().size()>4096)validatedTurns().clear();validatedTurns().insert(stamp);}
}
struct TomStore::Impl {
 std::filesystem::path root;int lock{-1};QJsonObject index;bool failed{};qint64 total{};Fault fault{Fault::None};
 explicit Impl(std::filesystem::path library):root(std::move(library)/"tom"){underlay::privateDirectory(root);underlay::privateDirectory(root/"conversations");lock=open((root/"store.lock").c_str(),O_RDWR|O_CREAT|O_NOFOLLOW|O_CLOEXEC,0600);need(lock>=0,"Tom store lock");try{struct stat st{};need(!fstat(lock,&st)&&S_ISREG(st.st_mode)&&st.st_uid==getuid()&&st.st_nlink==1&&(st.st_mode&0777)==0600,"Tom store unsafe");if(flock(lock,LOCK_EX|LOCK_NB)){if(errno==EWOULDBLOCK||errno==EAGAIN)throw std::runtime_error("Tom store busy");throw std::runtime_error("Tom store lock");}total=scan();if(std::filesystem::exists(root/"index.json"))index=indexAt(root);else{need(std::filesystem::is_empty(root/"conversations"),"Tom index missing with records");index={{"version",1},{"record","index"},{"conversations",QJsonArray{}},{"deleted",QJsonArray{}}};saveIndex();}recover();}catch(...){close(lock);lock=-1;throw;}}
 ~Impl(){if(lock>=0)close(lock);}
 qint64 scan(){qint64 bytes=0;unsigned count=0;for(auto& e:std::filesystem::recursive_directory_iterator(root)){need(++count<=8192,"Tom file count capacity");struct stat st{};need(!lstat(e.path().c_str(),&st)&&st.st_uid==getuid()&&!S_ISLNK(st.st_mode),"Tom tree ownership");if(S_ISDIR(st.st_mode)){need(!(st.st_mode&0077),"Tom directory mode");continue;}need(S_ISREG(st.st_mode)&&st.st_nlink==1&&(st.st_mode&0777)==0600,"Tom tree file type");bytes+=st.st_size;need(bytes<=MaxTotalBytes,"Tom total byte capacity");}return bytes;}
 void put(const std::filesystem::path& p,const QJsonObject& o,qint64 cap){need(!failed,"Tom reopen after storage error");auto b=envelope(o);need(b.size()<=cap,"Tom record capacity");qint64 old=0;struct stat st{};if(!lstat(p.c_str(),&st)){need(S_ISREG(st.st_mode)&&st.st_uid==getuid()&&st.st_nlink==1&&(st.st_mode&0777)==0600,"Tom replace ownership");old=st.st_size;}else need(errno==ENOENT,"Tom replace stat");need(total-old+b.size()<=MaxTotalBytes,"Tom total byte capacity");auto injected=fault;fault=Fault::None;try{need(injected!=Fault::BeforeReplace,"injected Tom before replace");underlay::atomicFile(p,b);total=total-old+b.size();need(injected!=Fault::AfterReplace,"injected Tom after replace");}catch(...){failed=true;throw;}}
 void saveIndex(){put(root/"index.json",index,512*1024);}
 QJsonObject manifest(const QString& c)const{need(visible(index,c),"Tom conversation missing or deleted");return manifestAt(root,c);}
 QJsonObject state(const QString& c,const QString& t)const{need(manifest(c)["turns"].toArray().contains(t),"Tom turn not in conversation");return stateAt(root,c,t);}
 void saveState(const QString& c,const QString& t,const QJsonObject& s){put(turnPath(root,c,t)/"state.json",s,16*1024*1024);
  if(terminal(s["status"].toString())&&s["purpose"]!="transcribe"){auto m=manifest(c);const auto preview=s["question"].toString().simplified().left(140);if(!preview.isEmpty()&&(m["preview"]!=preview||m["last_status"]!=s["status"]||m["last_turn"]!=t)){m["preview"]=preview;m["last_turn"]=t;m["last_status"]=s["status"];m["updated"]=double(QDateTime::currentSecsSinceEpoch());saveManifest(c,m);}}}
 void saveManifest(const QString& c,const QJsonObject& m){put(conversationPath(root,c)/"manifest.json",m,65536);}
 void finishDelete(const QString& c){auto p=conversationPath(root,c);if(std::filesystem::exists(p)){int fd=open(p.c_str(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);need(fd>=0,"Tom delete root");unsigned n=0;try{purge(fd,n);}catch(...){close(fd);throw;}close(fd);need(!rmdir(p.c_str()),"Tom delete root unlink");int parent=open((root/"conversations").c_str(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);need(parent>=0,"Tom delete parent");int synced=fsync(parent);close(parent);need(!synced,"Tom delete parent sync");}auto all=index["conversations"].toArray();for(int i=all.size()-1;i>=0;--i)if(all[i].toObject()["id"]==c)all.removeAt(i);auto deleted=index["deleted"].toArray();if(!deleted.contains(c)){need(deleted.size()<4096,"Tom deletion marker capacity");deleted.append(c);}index["deleted"]=deleted;index["conversations"]=all;index.remove("deleting");total=scan();saveIndex();}
 void recover(){if(index.contains("deleting"))finishDelete(index["deleting"].toString());if(index.contains("pending_conversation")){auto pending=index["pending_conversation"].toObject();auto id=pending["id"].toString();manifestAt(root,id);auto all=index["conversations"].toArray();all.append(pending);index["conversations"]=all;index.remove("pending_conversation");saveIndex();}unsigned turns=0;for(auto value:index["conversations"].toArray()){auto id=value.toObject()["id"].toString();auto m=manifestAt(root,id);QString preview;QString previewStatus,previewTurn;double previewUpdated{};if(m.contains("pending_turn")){auto t=m["pending_turn"].toString();auto d=read(turnPath(root,id,t)/"draft.json","draft",8*1024*1024);need(d["conversation"]==id&&d["turn"]==t,"Tom pending draft binding");decodeDraft(d["draft"].toObject());stateAt(root,id,t);auto all=m["turns"].toArray();if(!all.contains(t))all.append(t);m["turns"]=all;m["active_draft"]=t;m.remove("pending_turn");saveManifest(id,m);}for(auto tv:m["turns"].toArray()){need(++turns<=1024,"Tom total turn capacity");auto t=tv.toString();auto s=stateAt(root,id,t);if(terminal(s["status"].toString())&&s["purpose"]!="transcribe"&&!s["question"].toString().simplified().isEmpty()){preview=s["question"].toString().simplified().left(140);previewStatus=s["status"].toString();previewTurn=t;struct stat summaryStat{};need(!lstat((turnPath(root,id,t)/"state.json").c_str(),&summaryStat),"Tom summary timestamp");previewUpdated=double(summaryStat.st_mtim.tv_sec);}const auto stamp=turnStamp(turnPath(root,id,t));if(s["status"]!="draft"&&validatedTurn(stamp))continue; /* unchanged since this process validated it */auto d=read(turnPath(root,id,t)/"draft.json","draft",8*1024*1024);need(d["conversation"]==id&&d["turn"]==t,"Tom draft binding");auto original=decodeDraft(d["draft"].toObject());if(s["status"]=="draft"){auto updated=s;updated["question"]=original.correctedText.isEmpty()?original.question:original.correctedText;updated["scope"]=original.scope;updated["context"]=uiContext(original);updated["interpretation"]=original.interpretation;updated["local_document_id"]=original.localDocumentId;updated["has_handwriting"]=!original.originalHandwriting.isEmpty()||!original.handwritingImage.isEmpty();if(updated!=s){s=updated;saveState(id,t,s);}}if(std::filesystem::exists(turnPath(root,id,t)/"frozen.json")){auto f=frozenAt(root,id,t);need(f["draft_fingerprint"]==digest(json(d))&&f["context_fingerprint"]==digest(json(boundProvenance(decodeDraft(d["draft"].toObject()),QJsonDocument::fromJson(f["wire_body"].toString().toUtf8()).object()["purpose"].toString()))),"Tom frozen original draft changed");if(s["status"]=="draft"){s["status"]="frozen";s["request_id"]=f["request_id"];s["device_id"]=f["device_id"];auto wire=QJsonDocument::fromJson(f["wire_body"].toString().toUtf8()).object();s["provider"]=wire["provider"];s["model"]=wire["model"];s["max_output_tokens"]=wire["max_output_tokens"];s["purpose"]=wire["purpose"].toString("answer");if(wire.contains("illustration_model"))s["image_model"]=wire.value("illustration_model");saveState(id,t,s);}}else need(s["status"]=="draft","Tom frozen record missing");if(s["status"]!="draft")rememberTurn(turnStamp(turnPath(root,id,t)));}if(!preview.isEmpty()&&(m["preview"]!=preview||m["last_status"]!=previewStatus||m["last_turn"]!=previewTurn)){m["preview"]=preview;m["last_status"]=previewStatus;m["last_turn"]=previewTurn;m["updated"]=previewUpdated;saveManifest(id,m);}auto active=m["active_draft"].toString();if(!active.isEmpty()){auto activeState=stateAt(root,id,active);auto source=activeState["interpretation_for"].toString();if(!source.isEmpty()){need(uuid(source)&&m["turns"].toArray().contains(source),"Tom interpretation source missing");if(stateAt(root,id,source)["status"]=="draft"){m["active_draft"]=source;saveManifest(id,m);}}else if(activeState["create_attempted"].toBool()){m["active_draft"]=QJsonValue::Null;saveManifest(id,m);}}}}
};
TomStore::TomStore(std::filesystem::path root):impl_(std::make_unique<Impl>(std::move(root))){}TomStore::~TomStore()=default;void TomStore::injectFault(Fault f){impl_->fault=f;}
QString TomStore::createConversation(QString title){auto& x=*impl_;text(title,180,false);auto all=x.index["conversations"].toArray();need(all.size()<128,"Tom conversation capacity");QString id=newId();QJsonObject summary{{"id",id},{"title",title}};x.index["pending_conversation"]=summary;x.saveIndex();auto p=conversationPath(x.root,id);underlay::privateDirectory(p);underlay::privateDirectory(p/"turns");x.saveManifest(id,{{"version",1},{"record","conversation"},{"id",id},{"title",title},{"turns",QJsonArray{}},{"active_draft",QJsonValue::Null}});all.append(summary);x.index["conversations"]=all;x.index.remove("pending_conversation");x.saveIndex();return id;}
QString TomStore::saveDraft(const QString& c,const TomDraft& draft,QString t){auto& x=*impl_;auto d=draftObject(draft);auto m=x.manifest(c);bool fresh=t.isEmpty();if(fresh){unsigned total=0;for(auto v:x.index["conversations"].toArray())total+=manifestAt(x.root,v.toObject()["id"].toString())["turns"].toArray().size();need(total<1024&&m["turns"].toArray().size()<256,"Tom turn capacity");t=newId();m["pending_turn"]=t;x.saveManifest(c,m);underlay::privateDirectory(turnPath(x.root,c,t));}else{need(x.state(c,t)["status"]=="draft"&&!std::filesystem::exists(turnPath(x.root,c,t)/"frozen.json"),"Tom frozen draft immutable");}x.put(turnPath(x.root,c,t)/"draft.json",{{"version",1},{"record","draft"},{"conversation",c},{"turn",t},{"draft",d}},8*1024*1024);if(fresh){x.saveState(c,t,{{"version",1},{"record","turn"},{"conversation",c},{"turn",t},{"status","draft"},{"answer",""},{"cursor",0},{"events",QJsonObject{}},{"create_attempted",false},{"question",draft.correctedText.isEmpty()?draft.question:draft.correctedText},{"scope",draft.scope},{"context",uiContext(draft)},{"interpretation",draft.interpretation},{"local_document_id",draft.localDocumentId},{"has_handwriting",!draft.originalHandwriting.isEmpty()||!draft.handwritingImage.isEmpty()}});auto turns=m["turns"].toArray();turns.append(t);m["turns"]=turns;m.remove("pending_turn");}else{auto state=x.state(c,t);state["question"]=draft.correctedText.isEmpty()?draft.question:draft.correctedText;state["scope"]=draft.scope;state["context"]=uiContext(draft);state["interpretation"]=draft.interpretation;state["local_document_id"]=draft.localDocumentId;state["has_handwriting"]=!draft.originalHandwriting.isEmpty()||!draft.handwritingImage.isEmpty();x.saveState(c,t,state);}m["active_draft"]=t;x.saveManifest(c,m);return t;}
TomDraft TomStore::draft(const QString& c,const QString& t)const{impl_->state(c,t);auto record=read(turnPath(impl_->root,c,t)/"draft.json","draft",8*1024*1024);need(record["conversation"]==c&&record["turn"]==t,"Tom draft identity");return decodeDraft(record["draft"].toObject());}
void TomStore::linkInterpretation(const QString& c,const QString& interpretation,const QString& target){need(interpretation!=target,"Tom interpretation self link");auto& x=*impl_;auto i=x.state(c,interpretation),s=x.state(c,target);need(i["status"]=="draft"&&s["status"]=="draft","Tom interpretation draft state");auto input=draft(c,interpretation),source=draft(c,target);need(input.scope=="general"&&!input.handwritingImage.isEmpty()&&input.originalHandwriting==source.originalHandwriting&&!source.originalHandwriting.isEmpty(),"Tom interpretation original binding");auto original=read(turnPath(x.root,c,target)/"draft.json","draft",8*1024*1024);i["interpretation_for"]=target;i["interpretation_fingerprint"]=digest(json(original));x.saveState(c,interpretation,i);auto manifest=x.manifest(c);manifest["active_draft"]=target;x.saveManifest(c,manifest);}
bool TomStore::applyInterpretation(const QString& c,const QString& interpretation){auto& x=*impl_;auto i=x.state(c,interpretation);need(i["status"]=="completed"&&uuid(i["interpretation_for"].toString()),"Tom interpretation not complete");auto wire=QJsonDocument::fromJson(frozenAt(x.root,c,interpretation)["wire_body"].toString().toUtf8()).object();need(wire["purpose"]=="transcribe"&&wire["scope"]=="general"&&wire["context"].isNull(),"Tom interpretation wire scope");auto target=i["interpretation_for"].toString();auto state=x.state(c,target);if(state["status"]!="draft"||x.manifest(c)["active_draft"]!=target)return false;auto d=draft(c,target);auto answer=i["answer"].toString();if(d.interpretationTurn==interpretation&&d.interpretation==answer)return true;if(answer.isEmpty()||answer.size()>8000)return false;auto original=read(turnPath(x.root,c,target)/"draft.json","draft",8*1024*1024);if(digest(json(original))!=i["interpretation_fingerprint"])return false;d.interpretation=answer;d.interpretationTurn=interpretation;d.correctedText=answer;saveDraft(c,d,target);return true;}
TomHistory TomStore::history(const QString& c,const QString& device,const TomDraft& target,const QString& purpose)const{need(uuid(device),"Tom history device");auto& x=*impl_;auto m=x.manifest(c);TomHistory result;result.conversation_=c;result.device_=device;result.provenance_=digest(json(historyProvenance(target,purpose))).toLatin1();int total=target.question.size()+target.correctedText.size()+target.context["text"].toString().size();struct Pair{QString turn,question,answer;};std::vector<Pair> pairs;for(auto v:m["turns"].toArray()){auto t=v.toString();auto state=stateAt(x.root,c,t);if(state["status"]!="completed"){++result.excluded_;continue;}auto f=frozenAt(x.root,c,t);auto wire=QJsonDocument::fromJson(f["wire_body"].toString().toUtf8()).object();auto sourceBinding=f.value("provenance").toObject();if(wire.value("purpose")=="read-auto-answer"||wire.value("purpose")=="read-auto-scene-answer"){const auto original=read(turnPath(x.root,c,t)/"draft.json","draft",8*1024*1024);const auto originalDraft=decodeDraft(original.value("draft").toObject());need(digest(json(original))==f.value("draft_fingerprint")&&digest(json(boundProvenance(originalDraft,wire["purpose"].toString())))==f.value("context_fingerprint"),"Tom automatic history original binding");sourceBinding=historyProvenance(originalDraft,wire["purpose"].toString());}if(f["device_id"]!=device||digest(json(sourceBinding)).toLatin1()!=result.provenance_||(target.scope=="general"&&!sourceBinding.value("general_history_safe").toBool())){++result.excluded_;continue;}if(wire["purpose"]=="transcribe"){++result.excluded_;continue;}const bool read=readPurpose(wire["purpose"].toString()); /* its question is what Tom read */QString question=read?state["read_question"].toString():wire["question"].toString(),answer=state["answer"].toString();if(read&&question.isEmpty()){++result.excluded_;continue;}if(automaticPurpose(wire.value("purpose").toString()))try{answer=automaticDisplay(answer,true,automaticVersion(wire["purpose"].toString()));}catch(...){++result.excluded_;continue;}pairs.push_back({t,question,answer});}
  /* The newest completed turns that fit the service's limits (20 messages, 32000 characters with this question), oldest first.
     Older turns are left out of what is sent, never a failure: a long conversation keeps going instead of stopping Tom. */
  std::size_t first=pairs.size();while(first>0&&(pairs.size()-first+1)*2<=20&&total+pairs[first-1].question.size()+pairs[first-1].answer.size()<=32000){--first;total+=int(pairs[first].question.size()+pairs[first].answer.size());}
  result.excluded_+=int(first);for(auto i=first;i<pairs.size();++i){result.messages_.append(QJsonObject{{"role","user"},{"text",pairs[i].question}});result.messages_.append(QJsonObject{{"role","assistant"},{"text",pairs[i].answer}});result.turns_.append(pairs[i].turn);}return result;}
FrozenTomRequest TomStore::reviewedRequest(const QString& c,const QString& t,const TomConfig& config,const QString& device,const QJsonObject& wire,bool consent,bool images,const TomHistory& history)const{auto d=draft(c,t);need(impl_->state(c,t)["status"]=="draft"&&history.conversation_==c&&history.device_==device&&history.provenance_==digest(json(historyProvenance(d,wire["purpose"].toString()))).toLatin1()&&wire["conversation_id"]==c&&wire["scope"]==d.scope&&wire["context"]==draftObject(d)["context"]&&wire["question"]==(d.correctedText.isEmpty()?d.question:d.correctedText)&&wire["history"].toArray()==history.messages_,"Tom reviewed history provenance mismatch");return FrozenTomRequest(config,wire,consent,images,true);}
void TomStore::freezeForCreate(const QString& c,const QString& t,const FrozenTomRequest& frozen,const TomConfig& config,const QString& device,const TomHistory* history){auto& x=*impl_;auto state=x.state(c,t);need(state["status"]=="draft"&&uuid(device)&&frozen.acceptsConfig(config),"Tom freeze state or configuration");auto original=read(turnPath(x.root,c,t)/"draft.json","draft",8*1024*1024);auto d=decodeDraft(original["draft"].toObject());auto wire=QJsonDocument::fromJson(frozen.body()).object();need(wire["conversation_id"]==c&&uuid(wire["request_id"].toString())&&wire["question"]==(d.correctedText.isEmpty()?d.question:d.correctedText)&&wire["scope"]==d.scope&&wire["context"]==draftObject(d)["context"]&&wire.value("handwriting_image").toString()==d.handwritingImage&&wire.value("page_image").toString()==d.pageImage,"Tom frozen draft mismatch");auto binding=boundProvenance(d,wire["purpose"].toString());auto context=digest(json(binding));if(history){need(history->conversation_==c&&history->device_==device&&history->provenance_==digest(json(historyProvenance(d,wire.value("purpose").toString()))).toLatin1()&&wire["history"].toArray()==history->messages_,"Tom history provenance mismatch");}else need(wire["history"].toArray().isEmpty(),"Tom provenance-validated history required");for(auto cv:x.index["conversations"].toArray())for(auto tv:manifestAt(x.root,cv.toObject()["id"].toString())["turns"].toArray()){auto path=turnPath(x.root,cv.toObject()["id"].toString(),tv.toString())/"frozen.json";if(std::filesystem::exists(path)){auto existing=frozenAt(x.root,cv.toObject()["id"].toString(),tv.toString());need(existing["request_id"]!=wire["request_id"],"Tom request id already allocated");}}QJsonArray provenanceTurns;if(history)for(auto turn:history->turns_)provenanceTurns.append(turn);QJsonObject record{{"version",1},{"record","frozen"},{"conversation",c},{"turn",t},{"request_id",wire["request_id"]},{"device_id",device},{"config",configObject(config)},{"config_fingerprint",QString::fromLatin1(config.fingerprint)},{"wire_body",QString::fromUtf8(frozen.body())},{"wire_fingerprint",QString::fromLatin1(frozen.fingerprint())},{"context_fingerprint",context},{"provenance",binding},{"history_turns",provenanceTurns},{"draft_fingerprint",digest(json(original))}};x.put(turnPath(x.root,c,t)/"frozen.json",record,12*1024*1024);state["status"]="frozen";state["request_id"]=wire["request_id"];state["device_id"]=device;state["provider"]=wire["provider"];state["model"]=wire["model"];state["max_output_tokens"]=wire["max_output_tokens"];state["purpose"]=wire["purpose"].toString("answer");if(wire.contains("illustration_model"))state["image_model"]=wire.value("illustration_model");x.saveState(c,t,state);}
TomCreateAttempt TomStore::markCreateAttempt(const QString& c,const QString& t){auto& x=*impl_;auto state=x.state(c,t);need(state["status"]=="frozen"&&!state["create_attempted"].toBool(),"Tom create already attempted; reconcile without POST");auto f=frozenAt(x.root,c,t);auto config=parseTomConfig(json(f["config"].toObject()));const auto exactWire=QJsonDocument::fromJson(f["wire_body"].toString().toUtf8()).object();if(automaticPurpose(exactWire.value("purpose").toString())){config.sceneAnswer=exactWire["purpose"]=="auto-scene-answer";config.readSceneAnswer=exactWire["purpose"]=="read-auto-scene-answer";config.sceneMaxTokens=scenePurpose(exactWire["purpose"].toString())?exactWire["max_output_tokens"].toInt():0;config.sceneVersion=exactWire.value("scene_version").toInt(3);config.autoAnswer=exactWire.value("purpose")=="auto-answer";config.readAutoAnswer=exactWire.value("purpose")=="read-auto-answer";config.illustrationModel=exactWire.value("illustration_model").toString();}auto request=std::shared_ptr<const FrozenTomRequest>(new FrozenTomRequest(config,exactWire,true,true,(exactWire.value("purpose")=="read-auto-answer"||exactWire.value("purpose")=="read-auto-scene-answer")?historyProvenance(draft(c,t),exactWire["purpose"].toString()).value("general_history_safe").toBool():f["provenance"].toObject()["general_history_safe"].toBool()));need(request->body()==f["wire_body"].toString().toUtf8(),"Tom exact wire reconstruction");state["status"]="create-uncertain";state["create_attempted"]=true;x.saveState(c,t,state);auto manifest=x.manifest(c);if(manifest["active_draft"]==t){manifest["active_draft"]=QJsonValue::Null;x.saveManifest(c,manifest);}TomCreateAttempt result;result.request_=std::move(request);result.device_=f["device_id"].toString();return result;}
void TomStore::confirmCreate(const QString& c,const QString& t,const QJsonObject& ack){auto& x=*impl_;auto s=x.state(c,t);need(s["create_attempted"].toBool()&&ack["request_id"]==s["request_id"]&&ack["status"].isString()&&ack["replayed"].isBool(),"Tom create acknowledgement");if(!terminal(s["status"].toString())){s["status"]="receiving";s["remote_status"]=ack["status"];}x.saveState(c,t,s);}
bool TomStore::applyEvent(const QString& c,const QString& t,const QString& expectedRequest,const TomEvent& event){auto& x=*impl_;need(!x.failed,"Tom reopen after storage error");auto s=x.state(c,t);need(s["request_id"]==expectedRequest&&uuid(expectedRequest)&&s["create_attempted"].toBool()&&event.sequence>0&&event.sequence<=4096&&(event.kind=="delta"||event.kind=="status"||event.kind=="question"),"Tom event identity or capacity");auto key=QString::number(event.sequence);auto hashes=s["events"].toObject();auto fingerprint=digest(json({{"kind",event.kind},{"data",event.data}}));if(hashes.contains(key)){need(hashes[key]==fingerprint,"Tom changed event replay");x.saveState(c,t,s);return true;}need(event.sequence==quint64(s["cursor"].toInt())+1&&hashes.size()<4096,"Tom event sequence gap");QString field=event.kind=="status"?"status":"text";need(event.data.size()==1&&event.data[field].isString(),"Tom event schema");auto value=event.data[field].toString();text(value,event.kind=="delta"?16384:event.kind=="question"?8000:64,event.kind=="delta");need(!terminal(s["status"].toString())||(event.kind=="status"&&value==s["status"]),"Tom event after terminal state");if(event.kind=="question"){need((readPurpose(s["purpose"].toString()))&&!s.contains("read_question")&&s["answer"].toString().isEmpty(),"Tom question event");s["read_question"]=value;s["question"]=value;} /* once, before the answer */
 else if(event.kind=="delta"){auto answer=s["answer"].toString();need(answer.size()+value.size()<=262144,"Tom answer capacity");s["answer"]=answer+value;}else{s["remote_status"]=value;s["status"]=terminal(value)?value:QString("receiving");}hashes[key]=fingerprint;s["events"]=hashes;s["cursor"]=int(event.sequence);s.remove("error");x.saveState(c,t,s);return true;}
void TomStore::recordStatus(const QString& c,const QString& t,const QJsonObject& remote){auto& x=*impl_;auto s=x.state(c,t);need(s["create_attempted"].toBool()&&remote["request_id"]==s["request_id"]&&remote["status"].isString()&&remote["text"].isString(),"Tom status identity");text(remote["status"].toString(),64,false);text(remote["text"].toString(),262144);if(terminal(s["status"].toString()))need(remote["status"]==s["status"]&&remote["text"]==s["answer"],"Tom terminal snapshot changed");if(remote["error"].isString())text(remote["error"].toString(),512);else need(remote["error"].isNull(),"Tom status error schema");s["remote_status"]=remote["status"];s["remote_text"]=remote["text"];s["error"]=remote["error"];if(terminal(remote["status"].toString()))s["status"]=remote["text"]==s["answer"]?remote["status"]:QJsonValue("reconciling");x.saveState(c,t,s);}
void TomStore::recordFailure(const QString& c,const QString& t,const QString& code){need(QStringList{"network","service","stream","quota","unauthorized","cancel-uncertain","request-unavailable"}.contains(code),"Tom safe failure code");auto& x=*impl_;auto s=x.state(c,t);if(terminal(s["status"].toString()))return;s["error"]=code;if(code=="cancel-uncertain")s["status"]="cancel-uncertain";if(code=="request-unavailable"){need(s["create_attempted"].toBool(),"Tom unavailable request was never attempted");s["status"]="interrupted";} /* authenticated 404: retain ink, partial text and cursor; never recreate automatically */x.saveState(c,t,s);}
void TomStore::markCancelAttempt(const QString& c,const QString& t){auto& x=*impl_;auto s=x.state(c,t);need(s["create_attempted"].toBool()&&!terminal(s["status"].toString()),"Tom cancellation not active");s["status"]="cancel-uncertain";x.saveState(c,t,s);}
QString TomStore::explicitRetry(const QString& c,const QString& original,const FrozenTomRequest& frozen,const TomConfig& config,const QString& device,bool consent,const TomHistory* history){need(consent,"Tom renewed billable consent required");auto old=impl_->state(c,original);need(old["create_attempted"].toBool()&&(terminal(old["status"].toString())||old["status"]=="create-uncertain"),"Tom stop active request before retry");auto wire=QJsonDocument::fromJson(frozen.body()).object();need(wire["request_id"]!=old["request_id"],"Tom retry requires new request id");auto t=saveDraft(c,draft(c,original));freezeForCreate(c,t,frozen,config,device,history);return t;}
QJsonObject TomStore::deleteConversation(const QString& c,bool confirmed){need(confirmed,"Tom conversation delete confirmation required");auto& x=*impl_;auto m=x.manifest(c);for(auto t:m["turns"].toArray()){auto s=stateAt(x.root,c,t.toString());need(s["status"]=="draft"||s["status"]=="frozen"||terminal(s["status"].toString()),"Tom stop or reconcile active requests before deletion");}need(x.index["deleted"].toArray().size()<4096,"Tom deletion capacity");x.index["deleting"]=c;x.saveIndex();x.finishDelete(c);return {{"deleted",c},{"active_draft",QJsonValue::Null}};}
QJsonObject TomStore::listConversations(const std::filesystem::path& library){auto index=indexAt(library/"tom");QJsonArray visibleConversations;for(auto v:index["conversations"].toArray())if(visible(index,v.toObject()["id"].toString())){auto row=v.toObject();auto m=manifestAt(library/"tom",row["id"].toString());row["preview"]=m["preview"];row["updated"]=m["updated"];row["status"]=m["last_status"];row["latest_turn"]=m["last_turn"];row["turn_count"]=m["turns"].toArray().size();visibleConversations.append(row);}return {{"conversations",visibleConversations},{"incomplete_creation",index.contains("pending_conversation")}};}
QJsonObject TomStore::readTurn(const std::filesystem::path& library,const QString& c,const QString& t){auto root=library/"tom";need(visible(indexAt(root),c),"Tom conversation deleted");auto m=manifestAt(root,c);need(m["turns"].toArray().contains(t),"Tom turn missing");return stateAt(root,c,t);}
QJsonObject TomStore::readSnapshot(const std::filesystem::path& library,const QString& c,unsigned recent){need(recent<=256,"Tom snapshot capacity");auto root=library/"tom";if(!visible(indexAt(root),c))return {{"id",c},{"deleted",true},{"active_draft",QJsonValue::Null}};auto m=manifestAt(root,c);auto ids=m["turns"].toArray();QJsonArray turns;int begin=std::max(0,int(ids.size())-int(recent));for(int i=begin;i<ids.size();++i)turns.append(stateAt(root,c,ids[i].toString()));return {{"id",c},{"title",m["title"]},{"active_draft",m["active_draft"]},{"turns",turns},{"omitted_turns",begin},{"incomplete_creation",m.contains("pending_turn")}};}
}
